<template><el-button v-if="canExport" @click="visible=true">导出当前筛选</el-button><el-dialog v-model="visible" title="询盘导出" width="min(800px,calc(100vw - 32px))" append-to-body destroy-on-close><el-alert title="最多5000条，按当前筛选及你的负责人范围导出；超限会拒绝，不会截断。导出不含跟进时间线。" :closable="false"/><el-tabs v-model="tab" @tab-change="v=>v==='history'&&history()"><el-tab-pane label="导出文件" name="download"><p>默认联系方式遮蔽，正文及备注留空。</p><el-checkbox v-if="canPrivate" v-model="privateFields">包含完整联系方式、留言正文和处理备注</el-checkbox><el-button type="primary" :loading="busy" @click="download">下载XLSX</el-button></el-tab-pane><el-tab-pane label="导出记录" name="history"><el-button @click="history">刷新记录</el-button><el-table :data="rows"><el-table-column prop="createTime" label="时间" width="170"/><el-table-column prop="rowCount" label="行数" width="90"/><el-table-column prop="fileSha256" label="文件SHA256" show-overflow-tooltip/></el-table><pagination v-if="total" :total="total" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="history"/></el-tab-pane></el-tabs></el-dialog></template>
<script setup>
import{ref,reactive,watch,onBeforeUnmount,onDeactivated}from'vue';import{ElMessage}from'element-plus';import{saveAs}from'file-saver';import request from '@/utils/request';import auth from '@/plugins/auth';import{workflow}from'@/api/cms/workflow'
const props=defineProps({filter:{type:Object,required:true}}),canExport=auth.hasPermi('cms:inquiry:export'),canPrivate=auth.hasPermiAnd(['cms:inquiry:query','cms:inquiry:exportPrivate']),tab=ref('download'),visible=ref(false),privateFields=ref(false),busy=ref(false),rows=ref([]),total=ref(0),pg=reactive({pageNum:1,pageSize:10});let epoch=0;watch(visible,v=>{if(v){privateFields.value=false;pg.pageNum=1;tab.value='download'}else close()})
async function history(){const n=epoch,r=await workflow('inquiry/export/history','get',undefined,{...pg});if(n===epoch){rows.value=r.rows;total.value=r.total}}
async function download(){if(busy.value)return;const n=epoch;busy.value=true;try{const {pageNum,pageSize,...filters}=props.filter;const b=await request({url:'/cms/inquiry/export',method:'post',data:{...filters,includePrivate:privateFields.value},responseType:'blob',timeout:20000});if(n!==epoch)return;if(b.type.includes('json')){const e=JSON.parse(await b.text());ElMessage.error(e.msg||'导出未完成');return};saveAs(b,'询盘数据.xlsx');ElMessage.success('已生成并审计导出文件');await history()}finally{if(n===epoch)busy.value=false}}
function close(){++epoch;visible.value=false;privateFields.value=false;busy.value=false;rows.value=[]}onBeforeUnmount(close);onDeactivated(close)
</script>
